"""Generate docs/CONFLICTS.md from rows flagged source_conflict in data/processed/tests.csv (feeds the contradiction panel, M7)."""
import csv
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
rows = list(csv.DictReader(open(ROOT / 'data/processed/tests.csv', encoding='utf-8')))
conf = [r for r in rows if 'source_conflict' in r['quality_flags']]
L = ['# Source conflicts', '',
     'Generated by `scripts/make_conflicts.py` from rows flagged `source_conflict` in `data/processed/tests.csv`. A conflict is a genuine disagreement between two sources that cannot be resolved as an obvious error; '
     'the primary table value stays in the data and the other source\'s value is in `alt_value_report` (decision D24). Clear errors are corrected instead and flagged `corrected_from_report`. These entries will feed the contradiction panel.', '',
     '| test_id | field | value kept (source) | alternative (source) | note |', '|---|---|---|---|---|']
for r in conf:
    fld, _, rest = r['alt_value_report'].partition('=')
    L.append(f"| {r['test_id']} | {fld} | {r.get(fld, '')} cm/s (PSI-99, {r['source_ref']}) | {rest} | Report slide 29 prints 25 cm/s for sample 2-6; the PSI table prints 20 cm/s. Not resolved; do not average. |")
(ROOT / 'docs/CONFLICTS.md').write_text('\n'.join(L) + '\n', encoding='utf-8')
print('wrote docs/CONFLICTS.md', len(conf), 'conflicts')
